func newLoginServer(t *testing.T) (*Server, string) {
	t.Helper()
	tokenFile := filepath.Join(t.TempDir(), "token")
	token := strings.Repeat("s", 48)
	if err := os.WriteFile(tokenFile, []byte(token), 0o600); err != nil {
		t.Fatal(err)
	}
	server, err := NewServer(Config{ListenAddress: "10.0.0.4:9464", BearerTokenFile: tokenFile},
		ServerDeps{Registry: NewRegistry(false), Health: new(Health), Sessions: newTestSessionStore(t)})
	if err != nil {
		t.Fatal(err)
	}
	server.HandleLogin(http.HandlerFunc(func(writer http.ResponseWriter, _ *http.Request) {
		_, _ = writer.Write([]byte("login form"))
	}))
	server.Handle("GET /{$}", http.HandlerFunc(func(writer http.ResponseWriter, _ *http.Request) {
		_, _ = writer.Write([]byte("dashboard"))
	}))
	return server, token
}

func postLogin(server *Server, form url.Values, headers ...string) *httptest.ResponseRecorder {
	request := httptest.NewRequest(http.MethodPost, "/login", strings.NewReader(form.Encode()))
	request.Header.Set("Content-Type", "application/x-www-form-urlencoded")
	for index := 0; index+1 < len(headers); index += 2 {
		request.Header.Set(headers[index], headers[index+1])
	}
	recorder := httptest.NewRecorder()
	server.ServeHTTP(recorder, request)
	return recorder
}

func newTestSessionStore(t *testing.T) *SessionStore {
	t.Helper()
	srv, err := natsserver.NewServer(&natsserver.Options{Host: "127.0.0.1", Port: -1, JetStream: true,
		StoreDir: t.TempDir(), NoLog: true, NoSigs: true})
	if err != nil {
		t.Fatal(err)
	}
	go srv.Start()
	if !srv.ReadyForConnections(5 * time.Second) {
		t.Fatal("NATS did not start")
	}
	t.Cleanup(func() { srv.Shutdown(); srv.WaitForShutdown() })
	conn, err := nats.Connect(srv.ClientURL())
	if err != nil {
		t.Fatal(err)
	}
	t.Cleanup(conn.Close)
	js, err := jetstream.New(conn)
	if err != nil {
		t.Fatal(err)
	}
	store, err := OpenSessionStore(t.Context(), js, 1, "test")
	if err != nil {
		t.Fatal(err)
	}
	return store
}

type noSessionEnumeration struct{ jetstream.KeyValue }

func (noSessionEnumeration) Watch(context.Context, string, ...jetstream.WatchOpt) (jetstream.KeyWatcher, error) {
	return nil, errors.New("session enumeration unavailable")
}

func OpenSessionStore(ctx context.Context, js jetstream.JetStream, replicas int, scope string) (*SessionStore, error) {
	if js == nil || replicas < 1 || replicas > 5 || scope == "" {
		return nil, errors.New("dashboard sessions require JetStream, replicas and a listener scope")
	}
	kv, err := js.CreateOrUpdateKeyValue(ctx, jetstream.KeyValueConfig{
		Bucket: SessionBucket, Description: "Hashed dashboard sessions and token generations",
		History: 1, Storage: jetstream.FileStorage, Replicas: replicas,
		MaxValueSize: 1024, MaxBytes: 16 << 20,
	})
	if err != nil {
		return nil, err
	}
	leader, err := js.Conn().JetStream()
	if err != nil {
		return nil, err
	}
	stream, err := js.Stream(ctx, "KV_"+SessionBucket)
	if err != nil {
		return nil, err
	}
	return &SessionStore{kv: kv, leader: leader, scope: sessionHash(scope), stream: stream}, nil
}

func (store *SessionStore) get(ctx context.Context, key string) (*nats.RawStreamMsg, error) {
	msg, err := store.leader.GetLastMsg("KV_"+SessionBucket, "$KV."+SessionBucket+"."+key, nats.Context(ctx))
	if err != nil {
		return nil, err
	}
	if msg.Header.Get("KV-Operation") != "" {
		return nil, jetstream.ErrKeyNotFound
	}
	return msg, nil
}

func (binding *sessionBinding) latest(ctx context.Context) (*sessionBinding, error) {
	entry, err := binding.store.get(ctx, "token."+binding.store.scope)
	if errors.Is(err, nats.ErrMsgNotFound) || errors.Is(err, jetstream.ErrKeyNotFound) {
		return nil, nil
	}
	if err != nil {
		return nil, err
	}
	token, err := readSessionToken(entry.Data)
	if err != nil {
		return nil, err
	}
	if token.Hash == binding.tokenHash && token.Generation == binding.generation {
		return binding, nil
	}
	return &sessionBinding{store: binding.store, tokenHash: token.Hash, generation: token.Generation}, nil
}

func (manager *sessions) reconcile(ctx context.Context, binding *sessionBinding) (*sessionBinding, error) {
	latest, err := binding.latest(ctx)
	if latest != nil && latest.tokenHash != binding.tokenHash {
		return nil, nil
	}
	if latest != nil && latest != binding {
		manager.binding.CompareAndSwap(binding, latest)
	}
	return latest, err
}

func (manager *sessions) issue(ctx context.Context) (string, error) {
	ctx, cancel := context.WithTimeout(ctx, sessionStoreTimeout)
	defer cancel()
	binding := manager.binding.Load()
	if binding == nil && manager.local == nil {
		return "", errors.New("dashboard session store unavailable")
	}
	if binding != nil {
		var err error
		binding, err = manager.reconcile(ctx, binding)
		if err != nil {
			return "", err
		}
		if binding == nil {
			return "", errors.New("dashboard token retired")
		}
	}
	var raw [32]byte
	if _, err := rand.Read(raw[:]); err != nil {
		return "", err
	}
	encoded := base64.RawURLEncoding.EncodeToString(raw[:])
	if binding == nil {
		manager.mu.Lock()
		defer manager.mu.Unlock()
		if len(manager.local) >= maxSessions {
			return "", errSessionCapacity
		}
		value := "v3.0." + encoded
		manager.local[sessionHash(value)] = struct{}{}
		return value, nil
	}
	// Fixed CAS-allocated slots enforce capacity across all controllers,
	// including simultaneous logins. Only the cookie's digest is stored.
	start := (int(raw[0])<<8 | int(raw[1])) % maxSessions
	const probes = 8
	var occupied [maxSessions]bool
	for offset := range maxSessions + probes {
		if offset == probes {
			var err error
			occupied, err = binding.occupied(ctx)
			if err != nil {
				return "", err
			}
		}
		slot := (start + offset) % maxSessions
		if occupied[slot] {
			continue
		}
		value := "v3." + strconv.Itoa(slot) + "." + encoded
		revision, err := binding.store.kv.Create(ctx, binding.key(value), []byte(sessionHash(value)))
		if errors.Is(err, jetstream.ErrKeyExists) {
			occupied[slot] = true
			continue
		}
		if err != nil {
			return "", errors.Join(err, manager.rollback(ctx, sessionRollback{store: binding.store, key: binding.key(value), hash: sessionHash(value)}))
		}
		// Rotation can finish cleanup before this in-flight allocation commits.
		current, err := binding.current(ctx)
		if err != nil || !current {
			if err == nil {
				err = errors.New("dashboard token retired")
			}
			return "", errors.Join(err, manager.rollback(ctx, sessionRollback{store: binding.store, key: binding.key(value), revision: revision}))
		}
		return value, nil
	}
	return "", errSessionCapacity
}

func (server *Server) login(writer http.ResponseWriter, request *http.Request) {
	if server.token == nil {
		http.Redirect(writer, request, "/", http.StatusSeeOther)
		return
	}
	if !sameOriginForm(request) {
		writePlain(writer, http.StatusForbidden, "cross-site request refused\n")
		return
	}
	request.Body = http.MaxBytesReader(writer, request.Body, maxLoginFormSize)
	if err := request.ParseForm(); err != nil {
		writePlain(writer, http.StatusBadRequest, "invalid login form\n")
		return
	}
	next := LocalRedirectPath(request.PostForm.Get("next"))
	presented := strings.TrimSpace(request.PostForm.Get("token"))
	if subtle.ConstantTimeCompare([]byte(presented), server.token) != 1 {
		http.Redirect(writer, request, "/login?failed=1&next="+url.QueryEscape(next), http.StatusSeeOther)
		return
	}
	ctx, cancel := context.WithTimeout(request.Context(), sessionStoreTimeout)
	defer cancel()
	if cookie, err := request.Cookie(SessionCookieName); err == nil {
		valid, err := server.sessions.valid(ctx, cookie.Value)
		if err != nil {
			writePlain(writer, http.StatusServiceUnavailable, "session storage unavailable\n")
			return
		}
		if valid {
			http.SetCookie(writer, server.sessions.cookie(cookie.Value))
			http.Redirect(writer, request, next, http.StatusSeeOther)
			return
		}
	}
	value, err := server.sessions.issue(ctx)
	if err != nil {
		if errors.Is(err, errSessionCapacity) {
			writePlain(writer, http.StatusServiceUnavailable, "dashboard session limit reached; sign out in another browser or rotate the dashboard token\n")
			return
		}
		writePlain(writer, http.StatusServiceUnavailable, "session storage unavailable\n")
		return
	}
	http.SetCookie(writer, server.sessions.cookie(value))
	http.Redirect(writer, request, next, http.StatusSeeOther)
}

func parseProcStat(data []byte) (CPUSeconds, int, error) {
	var total CPUSeconds
	found := false
	cpus := 0
	scanner := bufio.NewScanner(bytes.NewReader(data))
	// The intr line holds one counter per IRQ and can exceed the default
	// 64 KiB token limit on large hosts; the whole file is already in memory.
	scanner.Buffer(make([]byte, 0, 64*1024), len(data)+1)
	for scanner.Scan() {
		fields := strings.Fields(scanner.Text())
		if len(fields) == 0 || !strings.HasPrefix(fields[0], "cpu") {
			continue
		}
		if fields[0] != "cpu" {
			cpus++
			continue
		}
		if len(fields) < 5 {
			return CPUSeconds{}, 0, errors.New("/proc/stat cpu line is short")
		}
		values := make([]float64, 8)
		for index := range values {
			if index+1 >= len(fields) {
				break
			}
			ticks, err := strconv.ParseUint(fields[index+1], 10, 64)
			if err != nil {
				return CPUSeconds{}, 0, errors.New("/proc/stat cpu line is malformed")
			}
			values[index] = float64(ticks) / userHZ
		}
		total = CPUSeconds{User: values[0], Nice: values[1], System: values[2], Idle: values[3],
			IOWait: values[4], IRQ: values[5], SoftIRQ: values[6], Steal: values[7]}
		found = true
	}
	if !found {
		return CPUSeconds{}, 0, errors.New("/proc/stat has no aggregate cpu line")
	}
	return total, cpus, scanner.Err()
}

func parseMeminfo(data []byte) (map[string]uint64, error) {
	values, err := parseKilobyteFields(data)
	if err != nil {
		return nil, err
	}
	if _, ok := values["MemTotal"]; !ok {
		return nil, errors.New("/proc/meminfo has no MemTotal")
	}
	return values, nil
}

func parseLoadavg(data []byte) (float64, float64, float64, error) {
	fields := strings.Fields(string(data))
	if len(fields) < 3 {
		return 0, 0, 0, errors.New("/proc/loadavg is malformed")
	}
	var loads [3]float64
	for index := range loads {
		value, err := strconv.ParseFloat(fields[index], 64)
		if err != nil {
			return 0, 0, 0, errors.New("/proc/loadavg is malformed")
		}
		loads[index] = value
	}
	return loads[0], loads[1], loads[2], nil
}

func parsePressure(data []byte) (PSI, error) {
	var psi PSI
	seen := false
	scanner := bufio.NewScanner(bytes.NewReader(data))
	for scanner.Scan() {
		fields := strings.Fields(scanner.Text())
		if len(fields) == 0 || fields[0] != "some" && fields[0] != "full" {
			continue
		}
		var avg10, avg60 float64
		var total uint64
		for _, field := range fields[1:] {
			key, raw, found := strings.Cut(field, "=")
			if !found {
				continue
			}
			var err error
			switch key {
			case "avg10":
				avg10, err = strconv.ParseFloat(raw, 64)
			case "avg60":
				avg60, err = strconv.ParseFloat(raw, 64)
			case "total":
				total, err = strconv.ParseUint(raw, 10, 64)
			}
			if err != nil {
				return PSI{}, errors.New("pressure line is malformed")
			}
		}
		if fields[0] == "some" {
			psi.SomeAvg10, psi.SomeAvg60, psi.SomeTotal = avg10, avg60, total
		} else {
			psi.FullAvg10, psi.FullAvg60, psi.FullTotal, psi.HasFullRow = avg10, avg60, total, true
		}
		seen = true
	}
	if !seen {
		return PSI{}, errors.New("pressure file has no some line")
	}
	return psi, scanner.Err()
}

func parseUptime(data []byte) (float64, error) {
	fields := strings.Fields(string(data))
	if len(fields) == 0 {
		return 0, errors.New("/proc/uptime is malformed")
	}
	return strconv.ParseFloat(fields[0], 64)
}

func readNetDev(path string) (rx, tx uint64, ok bool) {
	data, err := os.ReadFile(path)
	if err != nil {
		return 0, 0, false
	}
	for _, line := range strings.Split(string(data), "\n") {
		name, rest, found := strings.Cut(line, ":")
		fields := strings.Fields(rest)
		if !found || len(fields) < 9 || strings.TrimSpace(name) == "lo" {
			continue
		}
		received, errRx := strconv.ParseUint(fields[0], 10, 64)
		sent, errTx := strconv.ParseUint(fields[8], 10, 64)
		if errRx != nil || errTx != nil {
			continue
		}
		rx += received
		tx += sent
		ok = true
	}
	return rx, tx, ok
}

func parseStatusRSS(data []byte) uint64 {
	values, _ := parseKilobyteFields(data)
	return values["VmRSS"]
}

// parseKilobyteFields reads "Name: <n> kB" lines as bytes, the shared shape
// of /proc/meminfo and /proc/self/status.
func parseKilobyteFields(data []byte) (map[string]uint64, error) {
	values := map[string]uint64{}
	scanner := bufio.NewScanner(bytes.NewReader(data))
	for scanner.Scan() {
		name, rest, found := strings.Cut(scanner.Text(), ":")
		fields := strings.Fields(rest)
		if !found || len(fields) != 2 || fields[1] != "kB" {
			continue
		}
		if value, err := strconv.ParseUint(fields[0], 10, 64); err == nil {
			values[name] = value * 1024
		}
	}
	return values, scanner.Err()
}

func WriteSystemMetrics(w io.Writer, view SystemView) {
	cpu := view.CPUSeconds
	for _, mode := range []struct {
		name  string
		value float64
	}{{"user", cpu.User}, {"nice", cpu.Nice}, {"system", cpu.System}, {"idle", cpu.Idle},
		{"iowait", cpu.IOWait}, {"irq", cpu.IRQ}, {"softirq", cpu.SoftIRQ}, {"steal", cpu.Steal}} {
		WriteCounter(w, Series(MetricPrefix+"host_cpu_seconds_total", "mode", mode.name), mode.value)
	}
	WriteGauge(w, MetricPrefix+"host_cpus", float64(view.CPUCount))
	WriteGauge(w, MetricPrefix+"host_load1", view.Load1)
	WriteGauge(w, MetricPrefix+"host_load5", view.Load5)
	WriteGauge(w, MetricPrefix+"host_load15", view.Load15)
	WriteGauge(w, MetricPrefix+"host_memory_total_bytes", float64(view.MemTotalBytes))
	WriteGauge(w, MetricPrefix+"host_memory_available_bytes", float64(view.MemAvailBytes))
	WriteGauge(w, MetricPrefix+"host_swap_total_bytes", float64(view.SwapTotalBytes))
	WriteGauge(w, MetricPrefix+"host_swap_free_bytes", float64(view.SwapFreeBytes))
	WriteGauge(w, MetricPrefix+"host_uptime_seconds", view.UptimeSeconds)
	for _, resource := range []string{"cpu", "memory", "io"} {
		psi, ok := view.Pressure[resource]
		if !ok {
			continue
		}
		WriteGauge(w, Series(MetricPrefix+"host_pressure_avg10", "resource", resource, "kind", "some"), psi.SomeAvg10)
		WriteCounter(w, Series(MetricPrefix+"host_pressure_stalled_seconds_total", "resource", resource, "kind", "some"),
			float64(psi.SomeTotal)/1e6)
		if psi.HasFullRow {
			WriteGauge(w, Series(MetricPrefix+"host_pressure_avg10", "resource", resource, "kind", "full"), psi.FullAvg10)
			WriteCounter(w, Series(MetricPrefix+"host_pressure_stalled_seconds_total", "resource", resource, "kind", "full"),
				float64(psi.FullTotal)/1e6)
		}
	}
	if clock := view.Clock; clock != nil {
		synchronized := 0.0
		if clock.Synchronized {
			synchronized = 1
		}
		WriteGauge(w, MetricPrefix+"host_clock_synchronized", synchronized)
		WriteGauge(w, MetricPrefix+"host_clock_offset_seconds", clock.OffsetSeconds)
		WriteGauge(w, MetricPrefix+"host_clock_max_error_seconds", clock.MaxErrorSeconds)
	}
	for _, filesystem := range view.Filesystems {
		if filesystem.SizeBytes == 0 {
			continue
		}
		WriteGauge(w, Series(MetricPrefix+"host_filesystem_size_bytes", "role", filesystem.Role), float64(filesystem.SizeBytes))
		WriteGauge(w, Series(MetricPrefix+"host_filesystem_avail_bytes", "role", filesystem.Role), float64(filesystem.AvailBytes))
		WriteGauge(w, Series(MetricPrefix+"host_filesystem_files", "role", filesystem.Role), float64(filesystem.Files))
		WriteGauge(w, Series(MetricPrefix+"host_filesystem_files_free", "role", filesystem.Role), float64(filesystem.FilesFree))
	}
}

func ReadSystem(filesystems []FilesystemRole) (SystemView, error) {
	view, err := readSystem("/proc", filesystems, statFilesystem)
	view.Clock = readClock()
	return view, err
}

func readSystem(procRoot string, filesystems []FilesystemRole,
	stat func(string) (FilesystemView, error),
) (SystemView, error) {
	var view SystemView
	data, err := os.ReadFile(filepath.Join(procRoot, "stat"))
	if err != nil {
		return SystemView{}, err
	}
	if view.CPUSeconds, view.CPUCount, err = parseProcStat(data); err != nil {
		return SystemView{}, err
	}
	data, err = os.ReadFile(filepath.Join(procRoot, "meminfo"))
	if err != nil {
		return SystemView{}, err
	}
	memory, err := parseMeminfo(data)
	if err != nil {
		return SystemView{}, err
	}
	view.MemTotalBytes, view.MemAvailBytes = memory["MemTotal"], memory["MemAvailable"]
	view.SwapTotalBytes, view.SwapFreeBytes = memory["SwapTotal"], memory["SwapFree"]
	if data, err = os.ReadFile(filepath.Join(procRoot, "loadavg")); err == nil {
		view.Load1, view.Load5, view.Load15, _ = parseLoadavg(data)
	}
	if data, err = os.ReadFile(filepath.Join(procRoot, "uptime")); err == nil {
		view.UptimeSeconds, _ = parseUptime(data)
	}
	if data, err = os.ReadFile(filepath.Join(procRoot, "self", "status")); err == nil {
		view.ProcessRSSBytes = parseStatusRSS(data)
	}
	if rx, tx, ok := readNetDev(filepath.Join(procRoot, "net", "dev")); ok {
		view.NetRxBytes, view.NetTxBytes = rx, tx
	}
	for _, resource := range []string{"cpu", "memory", "io"} {
		data, err := os.ReadFile(filepath.Join(procRoot, "pressure", resource))
		if err != nil {
			continue
		}
		if psi, err := parsePressure(data); err == nil {
			if view.Pressure == nil {
				view.Pressure = map[string]PSI{}
			}
			view.Pressure[resource] = psi
		}
	}
	for _, filesystem := range filesystems {
		if filesystem.Role == "" || filesystem.Path == "" {
			continue
		}
		observed, err := stat(filesystem.Path)
		if err != nil {
			observed = FilesystemView{}
		}
		observed.Role, observed.Path = filesystem.Role, filesystem.Path
		view.Filesystems = append(view.Filesystems, observed)
	}
	return view, nil
}

func statFilesystem(path string) (FilesystemView, error) {
	var stat unix.Statfs_t
	if err := unix.Statfs(path, &stat); err != nil {
		return FilesystemView{}, err
	}
	blockSize := uint64(stat.Bsize)
	view := FilesystemView{SizeBytes: stat.Blocks * blockSize, AvailBytes: stat.Bavail * blockSize,
		FreeBytes: stat.Bfree * blockSize, Files: stat.Files, FilesFree: stat.Ffree}
	var info unix.Stat_t
	if err := unix.Stat(path, &info); err == nil {
		view.Device = uint64(info.Dev) // Dev is narrower on some architectures.
	}
	return view, nil
}

func readClock() *ClockView {
	var state unix.Timex
	status, err := unix.Adjtimex(&state)
	if err != nil {
		return nil
	}
	offset := float64(state.Offset) / 1e6 // microseconds unless STA_NANO
	if state.Status&unix.STA_NANO != 0 {
		offset = float64(state.Offset) / 1e9
	}
	return &ClockView{
		Synchronized:    status != unix.TIME_ERROR && state.Status&(unix.STA_UNSYNC|unix.STA_CLOCKERR) == 0,
		OffsetSeconds:   offset,
		MaxErrorSeconds: float64(state.Maxerror) / 1e6,
	}
}

